import re, base64
d=open('/tmp/o1.bin','rb').read()
# find all kitty APC sequences
parts = re.split(rb'(\x1b_G[^\x1b]*\x1b\\|\x1b\[[0-9;?]*[A-Za-z])', d)
events=[]
for p in parts:
    if p: events.append(p)
seqs=[]
for p in events:
    if p.startswith(b'\x1b_G'):
        seqs.append(('APC', p[:60].decode('latin1'), len(p)))
    elif p.startswith(b'\x1b['):
        seqs.append(('CSI', p.decode('latin1'), len(p)))
    else:
        seqs.append(('TXT', repr(p[:80]), len(p)))
# print sequence skeleton
for s in seqs:
    if s[2] < 400 or s[0]=='APC':
        print(s[0], s[1], s[2])
    else:
        print(s[0], '<big>', s[2])
EOF"}

