import an, collections
w,h,rows = an.load('/tmp/g1.png')
# extract connected components of alpha>100 pixels in the text bands
def comps(x0,x1,y0,y1):
    seen=set(); out=[]
    for y in range(y0,y1):
        for x in range(x0,x1):
            if (x,y) in seen: continue
            if rows[y][x*4+3]<=100: continue
            # BFS
            stack=[(x,y)]; pix=[]
            while stack:
                cx,cy=stack.pop()
                if (cx,cy) in seen: continue
                seen.add((cx,cy))
                if not (x0<=cx<x1 and y0<=cy<y1): continue
                if rows[cy][cx*4+3]<=100: continue
                pix.append((cx,cy))
                for dx in(-1,0,1):
                    for dy in(-1,0,1):
                        stack.append((cx+dx,cy+dy))
            if pix: out.append(pix)
    return out
# bottom x-axis labels
