    x0,x1,y0,y1=min(xs),max(xs),min(ys),max(ys)
    print("--- x=%d..%d y=%d..%d" % (x0,x1,y0,y1))
    for y in range(y0,y1+1):
        print(''.join('#' if (x,y) in set(c) else '.' for x in range(x0,x1+1)))
PY"}

