import an, collections
w,h,rows = an.load('/tmp/g1.png')
def comps(x0,x1,y0,y1,thr=60):
    seen=set(); out=[]
    for y in range(y0,y1):
        for x in range(x0,x1):
            if (x,y) in seen: continue
            if rows[y][x*4+3]<=thr: continue
            stack=[(x,y)]; pix=[]
            while stack:
                cx,cy=stack.pop()
                if (cx,cy) in seen: continue
                seen.add((cx,cy))
                if not (x0<=cx<x1 and y0<=cy<y1): continue
                if rows[cy][cx*4+3]<=thr: continue
                pix.append((cx,cy))
                for dx in(-1,0,1):
                    for dy in(-1,0,1):
                        stack.append((cx+dx,cy+dy))
            if pix: out.append(pix)
    return out
cs = comps(0,1592,962,977)
def bm(c):
    xs=[p[0] for p in c]; ys=[p[1] for p in c]
    x0,x1,y0,y1=min(xs),max(xs),min(ys),max(ys)
    s=set(c)
    return tuple(''.join('#' if (x,y) in s else '.' for x in range(x0,x1+1)) for y in range(y0,y1+1))
# normalize: shift y so that min y = 0? glyphs have different y0 (965 vs 964)
groups=collections.defaultdict(list)
for c in cs:
    b=bm(c)
    # shift to common origin: use y0-965 offset
    xs=[p[0] for p in c]; ys=[p[1] for p in c]
    x0,y0=min(xs),min(ys)
    y0n = y0 - 965
    shifted = tuple(''.join('#' if (x,y+y0n) in set(c) else '.' for x in range(x0,max(xs)+1)) for y in range(0,10))
    groups[shifted].append(min(xs))
for k,v in sorted(groups.items(), key=lambda kv: min(kv[1])):
    print("=== count %d, first x=%s" % (len(v), v[:6]))
    print('\n'.join(k))
