import an, collections
w,h,rows = an.load('/tmp/g1.png')
def comps(x0,x1,y0,y1,thr=60):
    seen=set(); out=[]
    for y in range(y0,y1):
        for x in range(x0,x1):
            if (x,y) in seen: continue
            if rows[y][x*4+3]<=thr: continue
            stack=[(x,y)]; pix=[]
            while stack:
                cx,cy=stack.pop()
                if (cx,cy) in seen: continue
                seen.add((cx,cy))
                if not (x0<=cx<x1 and y0<=cy<y1): continue
                if rows[cy][cx*4+3]<=thr: continue
                pix.append((cx,cy))
                for dx in(-1,0,1):
                    for dy in(-1,0,1):
                        stack.append((cx+dx,cy+dy))
            if pix: out.append(pix)
    return out
cs = comps(1543,1592,0,h)
# group into labels by y
lines=collections.defaultdict(list)
for c in cs:
    y0=min(p[1] for p in c)
    lines[y0].append(c)
def iou(a,b):
    sa,sb=set(a),set(b)
    if not sa or not sb: return 0
    # align by bounding box top-left
    def bbox(s): 
        xs=[p[0] for p in s]; ys=[p[1] for p in s]
        return min(xs),min(ys),max(xs),max(ys)
    ax0,ay0,ax1,ay1=bbox(sa); bx0,by0,bx1,by1=bbox(sb)
    best=0
    for dx in range(-2,3):
        for dy in range(-2,3):
            shifted={(x+dx-(ax0-bx0), y+dy-(ay0-by0)) for x,y in sa}
            inter=len(shifted&sb); union=len(shifted|sb)
            if union: best=max(best, inter/union)
    return best
templates = {
 '0': [(1573,242)],  # 0
 '1': [(1573,341)],
 '2': [(1573,307)],
 '3': [(1552,844)],
 '4': [(1564,172)],
 '5': [(1565,138)],
 '6': [(1573,373)],
 '7': [(1573,173)],
 '8': [(1565,107)],
 '9': [(1573,207)],
}
tp={}
for d,(x,y) in templates.items():
    tp[d]=set(next(c for c in cs if min(p[0] for p in c)==x and min(p[1] for p in c)==y))
# decode each label line
for y0 in sorted(lines):
    comps_ = sorted(lines[y0], key=lambda c: min(p[0] for p in c))
    # merge components that overlap in x (touching)
    s=''
    for c in comps_:
        cx=min(p[0] for p in c)
        best=None; bs=0
        for d,t in tp.items():
            v=iou(c,t)
            if v>bs: bs=v; best=d
        s += best if best else '?'
    print(y0, repr(s))
