import an, importlib, collections
d = importlib.import_module('decode')
def x0(c): return min(p[0] for p in c)
def x1(c): return max(p[0] for p in c)
def y0(c): return min(p[1] for p in c)
def y1(c): return max(p[1] for p in c)
def iou_sets(sa, sb, rng=2):
    best=0
    for dx in range(-rng,rng+1):
        for dy in range(-rng,rng+1):
            sh={(x+dx,y+dy) for x,y in sa}
            inter=len(sh&sb); union=len(sh|sb)
            if union: best=max(best,inter/union)
    return best
def build_templates(png):
    w,h,rows = an.load(png)
    cs = d.comps_fn(rows,w,h,0,w,960,978,60)
    cs.sort(key=x0)
    out=[]; cur=[cs[0]]
    for c in cs[1:]:
        if x0(c)-x1(cur[-1])<=4: cur.append(c)
        else: out.append(cur); cur=[c]
    out.append(cur)
    tpl=collections.defaultdict(list)
    n=len(out)
    for i,g in enumerate(out):
        if n<=1: break
        val = round(i*1.0/(n-1), 2)
        s = "%.2f" % val
        if len(s) != len(g):
            continue
        for ch, c in zip(s, sorted(g,key=x0)):
            tpl[ch].append(set(c))
    return rows, tpl, out
def classify(c, tpl, minv=0.35):
    s=set(c)
    best=None; bv=minv
    for k,instances in tpl.items():
        for inst in instances:
            v=iou_sets(s,inst)
            if v>bv: bv=v; best=k
    return best, bv
