package main

import (
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"
)

const helpText = `Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:

OPTIONS:
  -interval duration
    	When url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval. (default 1s)
  -rows int
    	Limits the height of the graph output.
  -steps int
    	Number of values to plot. (default 100)
  -url string
    	URL to fetch every second. Read JSON objects from stdin if not specified.

FIELD_SPEC: [<option>[,<option>...]:]path
  option:
    - counter: Computes the difference with the last value. The value must increase monotonically.
    - marker: When the value is none-zero, a vertical line is drawn.
  path:
    JSON field path (eg: field.sub-field).
`

// spec holds the parsed options of a single field specification
type spec struct {
	counter bool
	marker  bool
	path    string
}

func parseSpec(s string) spec {
	var sp spec
	if i := strings.Index(s, ":"); i >= 0 {
		for _, o := range strings.Split(s[:i], ",") {
			switch o {
			case "counter":
				sp.counter = true
			case "marker":
				sp.marker = true
			}
		}
		s = s[i+1:]
	}
	sp.path = s
	return sp
}

// fetcher provides a stream of json values
type fetcher func() (map[string]interface{}, error)

func urlFetcher(url string, interval time.Duration) fetcher {
	return func() (map[string]interface{}, error) {
		resp, err := http.Get(url)
		if err != nil {
			return nil, fmt.Errorf("input error: %v", err)
		}
		defer resp.Body.Close()
		var m map[string]interface{}
		if err := json.NewDecoder(resp.Body).Decode(&m); err != nil {
			return nil, fmt.Errorf("input error: %v", err)
		}
		return m, nil
	}
}

func stdinFetcher() fetcher {
	return func() (map[string]interface{}, error) {
		dec := json.NewDecoder(os.Stdin)
		var m map[string]interface{}
		if err := dec.Decode(&m); err != nil {
			return nil, fmt.Errorf("input error: %v", err)
		}
		return m, nil
	}
}

// get walks the json object and returns the numeric value at path
func get(m map[string]interface{}, path string) (float64, error) {
	parts := strings.Split(path, ".")
	cur := m
	for i, p := range parts {
		v, ok := cur[p]
		if !ok {
			return 0, fmt.Errorf("cannot get %s: %s does not exist.", path, p)
		}
		if i == len(parts)-1 {
			f, ok := v.(float64)
			if !ok {
				return 0, fmt.Errorf("invalid type %s: %T", path, v)
			}
			return f, nil
		}
		n, ok := v.(map[string]interface{})
		if !ok {
			var nilMap map[string]interface{}
			return 0, fmt.Errorf("cannot get %s: %s is not an object. %v", path, p, nilMap)
		}
		cur = n
	}
	return 0, nil
}

func main() {
	interval := flag.Duration("interval", time.Second, "When url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval.")
	rows := flag.Int("rows", 0, "Limits the height of the graph output.")
	steps := flag.Int("steps", 100, "Number of values to plot.")
	url := flag.String("url", "", "URL to fetch every second. Read JSON objects from stdin if not specified.")
	flag.Usage = func() {
		fmt.Fprint(os.Stderr, helpText)
	}
	flag.Parse()

	specs := make([]spec, 0, flag.NArg())
	for _, a := range flag.Args() {
		specs = append(specs, parseSpec(a))
	}
	if len(specs) == 0 {
		fmt.Fprintln(os.Stderr, "jplot: ", "no field spec provided")
		os.Exit(1)
	}

	if *url == "" {
		if isTerminal(os.Stdin) {
			fatal(errors.New("neither --url nor stdin is provided"))
		}
	}

	var fetch fetcher
	if *url != "" {
		fetch = urlFetcher(*url, *interval)
	} else {
		fetch = stdinFetcher()
	}

	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		runFetch(fetch, specs, *steps)
	}()

	term := detect()
	if err := run(*interval, *rows, *steps, specs, term); err != nil {
		fatal(err)
	}
	wg.Wait()
}

func fatal(err error) {
	fmt.Fprintln(os.Stderr, "jplot: ", err)
	os.Exit(1)
}

func itoa(i int) string { return strconv.Itoa(i) }
EOF
echo done"}

