package main

import (
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
	"syscall"
	"unsafe"
)

// Terminal describes how images can be pushed to the terminal
type Terminal interface {
	// CellSize returns the pixel size of a single character cell
	CellSize() (w, h int, err error)
	// Draw pushes an image to the terminal
	Draw(png []byte, id, prevID int) error
	// QuerySize asks the terminal for its pixel dimensions (CSI 14 t / OSC 1337)
	QuerySize() error
