// iTerm2 terminal
type iTerm2 struct{ t *tty }

func (i *iTerm2) QuerySize() error {
	os.Stdout.WriteString(itermQuery)
	return nil
}

func (i *iTerm2) CellSize() (int, int, error) {
	resp, err := i.t.response()
	if err != nil {
		return 0, 0, err
	}
	// expect OSC 1337;ReportCellSize=<height>x<width>
	s := resp
	s = strings.TrimPrefix(s, "\x1b]1337;ReportCellSize=")
	s = strings.TrimSuffix(s, "\x07")
	s = strings.TrimSuffix(s, "\x1b\\")
	parts := strings.Split(strings.TrimSpace(s), "x")
	if len(parts) != 2 {
		return 0, 0, errors.New("cannot get terminal cell size")
	}
	h, err1 := strconv.Atoi(strings.TrimSpace(parts[0]))
	w, err2 := strconv.Atoi(strings.TrimSpace(parts[1]))
	if err1 != nil || err2 != nil || h <= 0 || w <= 0 {
		return 0, 0, errors.New("cannot get terminal cell size")
	}
	return w, h, nil
}

func (i *iTerm2) Draw(png []byte, id, prev int) error {
	_, err := os.Stdout.WriteString("\x1b]1337;File=name=;size=" + itoa(len(png)) +
		";inline=1;width=100%;height=100%:" + base64Encode(png) + "\x1b\\")
	return err
}

func itoa(i int) string { return strconv.Itoa(i) }
