package main

import (
	"image"
	"image/color"
	"math"
)

// canvas is a simple RGBA canvas with alpha blending helpers
type canvas struct {
	img *image.RGBA
}

func newCanvas(w, h int) *canvas {
	return &canvas{img: image.NewRGBA(image.Rect(0, 0, w, h))}
}

func (c *canvas) blend(x, y int, col color.RGBA) {
	if x < 0 || y < 0 || x >= c.img.Rect.Dx() || y >= c.img.Rect.Dy() {
		return
	}
	i := c.img.PixOffset(x, y)
	a := col.A
	if a == 0 {
		return
	}
	d := c.img.Pix[i : i+4 : i+4]
	// straight alpha blending
	da := int(d[3])
	na := int(a)
	outA := na + da*(255-na)/255
	if outA == 0 {
		return
	}
	for k := 0; k < 3; k++ {
		s := int(col.R) >> (4 * (2 - k)) & 0xff
		switch k {
		case 0:
			s = int(col.R)
		case 1:
			s = int(col.G)
		case 2:
			s = int(col.B)
		}
		v := (s*na + int(d[k])*da*(255-na)/255) / outA
		d[k] = uint8(v)
	}
	d[3] = uint8(outA)
}

func (c *canvas) fillRect(x0, y0, x1, y1 float64, col color.RGBA) {
	if x1 < x0 {
		x0, x1 = x1, x0
	}
	if y1 < y0 {
		y0, y1 = y1, y0
	}
	for y := int(math.Floor(y0)); y <= int(math.Ceil(y1)); y++ {
		cy := float64(y) + 0.5
		if cy < y0 || cy >= y1 {
			// partial coverage
			cov := overlap(cy-0.5, cy+0.5, y0, y1)
			if cov <= 0 {
				continue
			}
			for x := int(math.Floor(x0)); x <= int(math.Ceil(x1)); x++ {
				cx := float64(x) + 0.5
				cxv := overlap(cx-0.5, cx+0.5, x0, x1)
				if cxv <= 0 {
					continue
				}
				cc := col
				cc.A = uint8(float64(col.A) * cov * cxv)
				c.blend(x, y, cc)
			}
			continue
		}
		for x := int(math.Floor(x0)); x <= int(math.Ceil(x1)); x++ {
			cx := float64(x) + 0.5
			cxv := overlap(cx-0.5, cx+0.5, x0, x1)
			if cxv <= 0 {
				continue
			}
			cc := col
			cc.A = uint8(float64(col.A) * cxv)
			c.blend(x, y, cc)
		}
	}
}

func overlap(a0, a1, b0, b1 float64) float64 {
	lo := math.Max(a0, b0)
	hi := math.Min(a1, b1)
	if hi <= lo {
		return 0
	}
	return hi - lo
}

// hline draws a horizontal line of the given thickness centred on y
func (c *canvas) hline(x0, x1, y float64, col color.RGBA) {
	c.fillRect(x0, y-0.5, x1, y+0.5, col)
}

// vline draws a vertical line of the given thickness centred on x
func (c *canvas) vline(x, y0, y1 float64, col color.RGBA) {
	c.fillRect(x-0.5, y0, x+0.5, y1, col)
}

func (c *canvas) line(x0, y0, x1, y1 float64, col color.RGBA) {
	// thick line using distance coverage
	const w = 1.0
	dx := x1 - x0
	dy := y1 - y0
	l := math.Hypot(dx, dy)
	if l == 0 {
		c.fillRect(x0-0.5, y0-0.5, x0+0.5, y0+0.5, col)
		return
	}
	nx := -dy / l
	ny := dx / l
	xmin := int(math.Floor(math.Min(x0, x1) - 2))
	xmax := int(math.Ceil(math.Max(x0, x1) + 2))
	ymin := int(math.Floor(math.Min(y0, y1) - 2))
	ymax := int(math.Ceil(math.Max(y0, y1) + 2))
	for y := ymin; y <= ymax; y++ {
		for x := xmin; x <= xmax; x++ {
			cx := float64(x) + 0.5
			cy := float64(y) + 0.5
			// projection parameter
			t := ((cx-x0)*dx + (cy-y0)*dy) / (l * l)
			if t < 0 {
				t = 0
			} else if t > 1 {
				t = 1
			}
			px := x0 + t*dx
			py := y0 + t*dy
			d := math.Hypot(cx-px, cy-py)
			if d > w/2 {
				continue
			}
			cov := 1 - d/(w/2)
			cc := col
			cc.A = uint8(float64(col.A) * cov)
			c.blend(x, y, cc)
		}
	}
}
