package main

import (
	"image/color"
	"math"
	"sort"
)

var palette = []color.RGBA{
	{0, 116, 217, 255},
	{217, 101, 0, 255},
	{17, 207, 194, 255},
	{217, 0, 116, 255},
	{0, 217, 210, 255},
	{0, 217, 101, 255},
}

const (
	legendBG   = color.RGBA{0, 0, 0, 100}
	gridColor  = color.RGBA{180, 180, 180, 128}
	labelColor = color.RGBA{180, 180, 180, 255}
	textColor  = color.RGBA{250, 250, 250, 248}
)

// sample series for a single graph
type series struct {
	spec   spec
	values []float64
	marker []bool
	last   float64
	has    bool
}

type graph struct {
	series   []*series
	max      float64
	plots    int // number of plot positions (steps)
	nameW    int
}

const (
	axisInsetX   = 12 // left offset of the plot area from image edge
	axisInsetTop = 10
	bottomGap    = 27
	labelGap     = 11 // gap between plot right edge and y labels
	xticks       = 30
	yticks       = 29
)

// scale converts a font unit size to pixels
const fontScale = 10.0 / float64(capH)

func glyphWidth(s string) float64 {
	return float64(measure(s)) * fontScale
}

// drawText renders a string with the baseline at (x, y)
func (c *canvas) drawText(x, y float64, s string, col color.RGBA) {
	cx := x
	for _, r := range s {
		g, ok := fontData[r]
		if !ok {
			g = fontData[' ']
		}
		scale := fontScale
		for _, sg := range g.segs {
			x0 := cx + sg.x0*scale
			y0 := y + sg.y0*scale
			x1 := cx + sg.x1*scale
			y1 := y + sg.y1*scale
			if sg.curve {
				drawQuad(c, x0, y0, cx+sg.qx*scale, y+sg.qy*scale, x1, y1, col)
			} else {
				c.line(x0, y0, x1, y1, col)
			}
		}
		cx += float64(g.advance) * scale
	}
}

func drawQuad(c *canvas, x0, y0, cx, cy, x1, y1 float64, col color.RGBA) {
	const n = 8
	px, py := x0, y0
	for i := 1; i <= n; i++ {
		t := float64(i) / n
		mt := 1 - t
		nx := mt*mt*x0 + 2*mt*t*cx + t*t*x1
		ny := mt*mt*y0 + 2*mt*t*cy + t*t*y1
		c.line(px, py, nx, ny, col)
		px, py = nx, ny
	}
}

// fmtTick formats a tick label
func fmtTick(v float64, all []float64) string {
	if v == math.Round(v) && math.Abs(v) < 1e15 {
		return itoa(int(math.Round(v)))
	}
	// choose a precision that separates all values
	prec := 0
	for prec < 8 {
		seen := map[string]bool{}
		ok := true
		for _, t := range all {
			s := trimZeros(sprintfPct(t, prec))
			if seen[s] {
				ok = false
				break
			}
			seen[s] = true
		}
		if ok {
			break
		}
		prec++
	}
	return trimZeros(sprintfPct(v, prec))
}

func sprintfPct(v float64, prec int) string {
	s := ""
	if prec == 0 {
		s = itoa(int(math.Round(v)))
	} else {
		s = itoa(int(math.Round(v*math.Pow10(prec))))
		if len(s) <= prec {
			s = string(make([]byte, prec-len(s)+1-len(s))) + s
		}
		for len(s) <= prec {
			s = "0" + s
		}
		s = s[:len(s)-prec] + "." + s[len(s)-prec:]
	}
	return s
}

func trimZeros(s string) string {
	for len(s) > 1 && s[len(s)-1] == '0' && containsDot(s) {
		s = s[:len(s)-1]
	}
	if len(s) > 1 && s[len(s)-1] == '.' {
		s = s[:len(s)-1]
	}
	return s
}

func containsDot(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] == '.' {
			return true
		}
	}
	return false
}

// render draws all graphs into a new canvas and returns it
func renderGraph(g *graph, rows, cols, w, h int) *canvas {
	c := newCanvas(w, h)
	n := len(g.series)
	graphH := h / n
	if graphH < 1 {
		graphH = 1
	}
	left := float64(axisInsetX) + 0.5
	// determine y label widths
	plotTop := float64(axisInsetTop)
	plotBottom := float64(graphH - bottomGap)
	plotH := plotBottom - plotTop
	// y tick values
	ticks := make([]float64, yticks)
	for i := 0; i < yticks; i++ {
		ticks[i] = g.max * float64(i) / float64(yticks-1)
	}
	labels := make([]string, yticks)
	widest := 0.0
	for i, t := range ticks {
		labels[i] = fmtTick(t, ticks)
		if lw := glyphWidth(labels[i]); lw > widest {
			widest = lw
		}
	}
	plotRight := float64(w) - 10.5 - widest
	plotW := plotRight - left

	for gi := 0; gi < n; gi++ {
		top := plotTop + float64(gi*graphH)
		bottom := plotBottom + float64(gi*graphH)
		c.vline(left-0.5, top+2, bottom, gridColor)
		c.vline(plotRight, top, bottom+4, gridColor)
		// draw areas and lines
		s := g.series[gi]
		drawSeries(c, s, left, plotW, top, plotH, gi)
		// y ticks and labels
		for i := 0; i < yticks; i++ {
			y := bottom - plotH*float64(i)/float64(yticks-1)
			if i > 0 {
				c.hline(plotRight+2, plotRight+5, y, gridColor)
				c.vline(plotRight+3.5, y-1, y+1, gridColor)
			}
			lw := glyphWidth(labels[i])
			c.drawText(plotRight+labelGap, y+5, labels[i], labelColor)
			_ = lw
		}
	}
	// x axis labels are drawn once, at the bottom of the image
