	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"sync"
	"time"
)

// graph holds the collected series data
type graphT struct {
	series []*series
	max    float64
}

var current = &graphT{}
var mu sync.Mutex

// runFetch collects values from the data source until EOF
func runFetch(fetch fetcher, specs []spec, steps int) {
	ticker := time.NewTicker(time.Millisecond)
	defer ticker.Stop()
	for {
		m, err := fetch()
		if err != nil {
			fatal(fmt.Errorf("Data source error:  %s", err.Error()))
			return
		}
		vals := make([]float64, len(specs))
		for i, s := range specs {
			v, err := get(m, s.path)
			if err != nil {
				fatal(fmt.Errorf("Data source error:  %s", err.Error()))
				return
			}
			vals[i] = v
		}
		mu.Lock()
		for i, s := range specs {
			var sr *series
			for _, x := range current.series {
				if x.spec.path == s.path {
					sr = x
					break
			}
			}
			if sr == nil {
				sr = &series{spec: s}
				current.series = append(current.series, sr)
			}
			v := vals[i]
			if s.counter && sr.has {
				v = vals[i] - sr.last
			}
			sr.last = vals[i]
			sr.has = true
			sr.values = append(sr.values, v)
			sr.marker = append(sr.marker, v != 0)
			if v > current.max {
				current.max = v
			}
		}
		mu.Unlock()
		time.Sleep(50 * time.Millisecond)
	}
}

func buildGraph(specs []spec) *graph {
	mu.Lock()
	defer mu.Unlock()
	g := &graph{}
	for _, s := range current.series {
		cp := &series{spec: s.spec, values: append([]float64{}, s.values...), marker: append([]bool{}, s.marker...)}
		g.series = append(g.series, cp)
	}
	g.max = current.max
	return g
}

// urlFetcher returns a fetcher for a URL
func newURLFetcher(url string) fetcher {
	return func() (map[string]interface{}, error) {
		resp, err := http.Get(url)
		if err != nil {
			return nil, fmt.Errorf("input error: %v", err)
		}
		defer resp.Body.Close()
		var m map[string]interface{}
		if err := json.NewDecoder(resp.Body).Decode(&m); err != nil {
			return nil, fmt.Errorf("input error: %v", err)
		}
		return m, nil
	}
}

// stdinFetcher reads a single json object per call
func newStdinFetcher() fetcher {
	dec := json.NewDecoder(os.Stdin)
	return func() (map[string]interface{}, error) {
		var m map[string]interface{}
		if err := dec.Decode(&m); err != nil {
			return nil, fmt.Errorf("input error: %v", err)
		}
		return m, nil
	}
}
